#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <openssl/sha.h>

#define TMP_FILE "/tmp/validation_file"
#define MARKER "HARMLESS_MARKER_STRING"

int createTempFile() {
    int fd = open(TMP_FILE, O_CREAT | O_RDWR, 0600);
    if (fd < 0) {
        perror("Error creating temporary file");
        return -1;
    }
    close(fd);
    return 0;
}

int appendMarkerToFile() {
    int fd = open(TMP_FILE, O_RDWR);
    if (fd < 0) {
        perror("Error opening temporary file for appending");
        return -1;
    }
    if (lseek(fd, 0, SEEK_END) < 0) {
