    unsigned char expectedHash[SHA256_DIGEST_LENGTH] = { /* ... */ };
    if (memcmp(hash, expectedHash, SHA256_DIGEST_LENGTH) != 0) {
        printf("Checksum verification failed\n");
        return -1;
    }
    return 0;
}

int cleanup() {
    if (remove(TMP_FILE) != 0) {
        perror("Error removing temporary file");
        return -1;
    }
    return 0;
}

int main() {
    if (createTempFile() != 0) {
